from __future__ import annotations
import html
import json
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
DOC = ROOT / "docs"
EV = ROOT / "evidence"


def esc(x: object) -> str:
    return html.escape(str(x), quote=True)


def shell(title: str, here: str, body: str) -> str:
    nav_items = [
        ("hsl.html", "H77-HSL Overview"),
        ("hsl-executive-summary.html", "HSL Executive Summary & Submit Guide"),
        ("index.html", "All GEMSDOE77 Lanes"),
        ("executive-summary.html", "Repository Submission Guide"),
        ("lia-analysis.html", "Why 0.2778 Analysis"),
        ("contactphys.html", "Contact-Physics Lane"),
        ("lia.html", "LIA Lane"),
    ]
    nav_html = " ".join(
        f'<a href="{href}"{" class=here" if href == here else ""}>{esc(label)}</a>'
        for href, label in nav_items
    )
    return f"""<!doctype html><html lang="en"><head><meta charset="utf-8">
<meta name="viewport" content="width=device-width,initial-scale=1"><title>{esc(title)} · GEMSDOE77</title>
<link rel="stylesheet" href="assets/lia.css"></head><body>
<header><div class="wrap"><span class="brand">GEMSDOE77 · DOE GEMS Prize (Lane H77-HSL)</span>{nav_html}
<a href="https://github.com/buffedlizard55-lab/GEMSDOE77">GitHub</a></div></header>
<main><div class="wrap">{body}</div></main>
<footer><div class="wrap">Under Parallel-Run Protocol Rule 6, promotion to a real weekly slot is a separate human selector step (weekly_slots_used = 0; automatic weekly-slot consumption is not approved without human selector sign-off). Generated by <code>scripts/hsl_build_site.py</code> from <code>evidence/run_card_hsl.json</code>, <code>evidence/hsl_holdout_exp1.json</code>, <code>evidence/hsl_holdout_exp2_replication.json</code>, and <code>evidence/hsl_exp3_submission.json</code>. Labels: <b>ORGANIZER-CONFIRMED</b> (public leaderboard receipt), <b>OWNER-REPORT</b> (transcribed from submission receipt), <b>HOLDOUT-DTI</b> (local hide-and-recover evaluator <code>gems57-pooled-hide-v2</code>).</div></footer>
<script>document.querySelectorAll('button[data-copy]').forEach(b=>b.onclick=()=>{{navigator.clipboard.writeText(b.dataset.copy);b.textContent='Copied';setTimeout(()=>b.textContent='Copy',1200)}})</script>
</body></html>"""


